-- GENERATED by `python3 analytics/build.py render` from analytics/dbt/models/marts/fact_lab_result.sql. Do not edit.
-- Fact lab result. Grain: one row per numeric lab result (silver_observation, category laboratory, a number and an
-- effective time). Results like <0.01 are kept with their comparator and no range flag.
-- Incremental on the effective date, with a watermark per source: MIMIC dates are shifted into the 2100s, so one
-- watermark for all sources would never let a new live feed result in. Each run reloads the last 3 days of each source
-- (late and corrected results replace their row by key), new sources in full, and every result of a record whose person
-- changed since it was loaded (an EMPI link made or undone moves the record to another master id). A result changed more
-- than 3 days after its effective date, or deleted on the server, needs dbt build --full-refresh.
CREATE OR REPLACE TABLE fact_lab_result AS
WITH keys AS (
    SELECT * FROM int_patient_key
),
results AS (
    SELECT
        MD5((SELECT pseudonym_salt FROM governance_settings) || '|' || COALESCE(CAST(o.observation_id AS VARCHAR), ''))                                           AS lab_result_sk,
        k.patient_sk,
        k.patient_record_sk,
        CASE WHEN o.encounter_id IS NOT NULL THEN MD5((SELECT pseudonym_salt FROM governance_settings) || '|' || COALESCE(CAST(o.encounter_id AS VARCHAR), '')) END AS encounter_sk,
        CASE WHEN o.loinc IS NULL THEN 'unknown'
             ELSE MD5(COALESCE(CAST(o.loinc AS VARCHAR), '')) END                                   AS lab_sk,
        CAST(EXTRACT(YEAR FROM CAST(o.effective_at AS DATE)) * 10000 + EXTRACT(MONTH FROM CAST(o.effective_at AS DATE)) * 100 + EXTRACT(DAY FROM CAST(o.effective_at AS DATE)) AS INTEGER)                                   AS effective_date_key,
        CAST(o.effective_at AS DATE)                                                     AS effective_date,
        o.effective_at,
        k.source,
        o.loinc,
        o.value_num,
        o.comparator,
        o.unit,
        o.ref_low,
        o.ref_high,
        o.range_flag
    FROM silver_observation o
    JOIN keys k ON k.patient_id = o.patient_id
    WHERE o.category = 'laboratory' AND o.value_num IS NOT NULL AND o.effective_at IS NOT NULL
)
SELECT r.*
FROM results r;
